/**
 * Course profiles (P1b): the ONE place the runtime learns what a course can
 * do. Generated by the compiler into src/content/course-profiles.json from
 * which artifacts exist for the course's target language, plus an explicit
 * `enabled` override in content/courses/<id>.profile.json. Nothing in src/
 * may branch on a course or language literal — it asks the profile.
 *
 * Replaces capabilities.ts (hand-set rollout flags) and every course-id
 * equality check the runtime used to carry.
 */

import profilesJson from "../content/course-profiles.json";

export type CourseCapabilities = {
  /** FSRS scheduler + stable item ids + evidence gate (vs the legacy SM-2 translation). */
  fsrs: boolean;
  /** TODAY tab + guided daily session. */
  dailySession: boolean;
  /** Rich lexicon + vocabulary browser. */
  lexicon: boolean;
  /** Pedagogy concept steps + concept cards. */
  concepts: boolean;
  /** Placement diagnostic (`/placement/*`). */
  placement: boolean;
  /** Scored checkpoints + capstone (`/checkpoint/[id]`). */
  checkpoints: boolean;
  /** Can-do goals screen + level estimate (`/goals`). */
  goals: boolean;
  /** Listening review + listening exercises. */
  listening: boolean;
  /** Reading comprehension content. */
  reading: boolean;
  /** Speaking review + spoken production. */
  speaking: boolean;
  /** Writing practice with rubric feedback. */
  writing: boolean;
  /** Conversation practice scenarios. */
  conversation: boolean;
  /** P3d: an exam track (format practice + timed mock); absent = none. */
  exam?: boolean;
  /** P5b: graded stories ("Đọc & nghe"); absent = none. */
  stories?: boolean;
};

export type CourseArtifactPaths = {
  /** P3d: compiled exam tracks of the course (DELE A1, JLPT N5, …). */
  examTracks?: string;
  /** P3e: the daily-new-words syllabus (target-level delivery order + unlock units). */
  dailyWords?: string;
  /** P5b: graded stories (per native language) + their sentence-audio module. */
  stories?: string;
  storyAssets?: string;
  ids?: string;
  lexiconIndex?: string;
  lexiconFallback?: string;
  lexiconDb?: string;
  concepts?: string;
  objectives?: string;
  checkpoints?: string;
  placement?: string;
  attainment?: string;
  claim?: string;
  listening?: string;
  reading?: string;
  clipAssets?: string;
  speech?: string;
  writing?: string;
  scenarios?: string;
};

export type CourseProfile = {
  id: string;
  targetCode: string;
  nativeCode: string;
  targetLanguage: string;
  nativeLanguage: string;
  /** Emoji flag from the pack (chrome fallback). */
  flag: string;
  /** Country code of the bundled round flag asset (assets/images/flags/<code>.svg). */
  flagAsset: string;
  recognitionLocale: string;
  ttsLocale: string;
  script: "latin" | "japanese" | "han" | "hangul";
  /** Stable item-id prefix (`fr:w:`); empty when the course has no id registry. */
  idPrefix: string;
  /** Reversible legacy-id prefix (`fr:legacy:`). */
  legacyIdPrefix: string;
  capabilities: CourseCapabilities;
  artifacts: CourseArtifactPaths;
  /** P3d: "standalone" = an inherited course kept beside its target's primary course (no rich layers). */
  role?: "standalone";
  /**
   * P4a: not offered in onboarding — listed under "Other courses" in the
   * course switcher (a standalone course, or a basic pack whose target has
   * an A1-claimable Vietnamese course). Migration-free: no learner data moves.
   */
  hiddenFromOnboarding?: true;
  /** P3e §8: content still under native review — the Learn tab shows a beta banner. */
  beta?: true;
  /** D-10: reviewed by an AI-simulated native reviewer (owner-accepted) — course info and Licences show an honest note. */
  reviewNote?: "ai-simulated";
  /**
   * The course whose pack-audio manifest entries this course plays (P2b):
   * set only for a course in a secondary native language — the audio is
   * the target language's, recorded once for the primary course.
   */
  audioCourseId?: string;
};

export const NO_CAPABILITIES: CourseCapabilities = {
  fsrs: false,
  dailySession: false,
  lexicon: false,
  concepts: false,
  placement: false,
  checkpoints: false,
  goals: false,
  listening: false,
  reading: false,
  speaking: false,
  writing: false,
  conversation: false,
};

type ProfilesArtifact = {
  version: number;
  defaultCourseId: string;
  defaultCourseByNative?: Record<string, string>;
  profiles: Record<string, CourseProfile>;
};

const PROFILES = (profilesJson as ProfilesArtifact).profiles;

/** The compiler-chosen onboarding default (the most complete course). */
export function defaultCourseId(): string {
  return (profilesJson as ProfilesArtifact).defaultCourseId;
}

/**
 * P3e §7: the onboarding preselection for a UI language — the first course
 * explained in that language in the compiler's default order (`vi` → fr-vi,
 * `en` → fr-en), else the global default. Not the migration default
 * (LEGACY_FLAT_COURSE_ID in persistence/migrations.ts).
 */
export function defaultCourseForUi(uiLanguage: string): string {
  const artifact = profilesJson as ProfilesArtifact;
  return artifact.defaultCourseByNative?.[uiLanguage] ?? artifact.defaultCourseId;
}

/** Test seam: capability overrides (e.g. FSRS on a legacy course) — bun/jest only. */
const TEST_OVERRIDES = new Map<string, Partial<CourseCapabilities>>();

/** Test seam (P1c): whole profiles of TEST-ONLY courses (src/content/test-only/course-profiles.json). */
const TEST_PROFILES = new Map<string, CourseProfile>();

export function __registerCourseProfileForTests(profile: CourseProfile | null, courseId?: string): void {
  if (profile === null) TEST_PROFILES.delete(courseId ?? "");
  else TEST_PROFILES.set(profile.id, profile);
}

export function __setCourseCapabilityOverrideForTests(
  courseId: string,
  override: Partial<CourseCapabilities> | null
): void {
  if (override === null) TEST_OVERRIDES.delete(courseId);
  else TEST_OVERRIDES.set(courseId, override);
}

function unknownProfile(courseId: string): CourseProfile {
  const [targetCode = "", nativeCode = ""] = courseId.split("-");
  return {
    id: courseId,
    targetCode,
    nativeCode,
    targetLanguage: targetCode,
    nativeLanguage: nativeCode,
    flag: "",
    flagAsset: "",
    recognitionLocale: targetCode,
    ttsLocale: targetCode,
    script: "latin",
    idPrefix: "",
    legacyIdPrefix: "",
    capabilities: NO_CAPABILITIES,
    artifacts: {},
  };
}

/** The profile for a course; a fully-gated placeholder for unknown ids (never throws). */
export function courseProfile(courseId: string): CourseProfile {
  const base = TEST_PROFILES.get(courseId) ?? PROFILES[courseId] ?? unknownProfile(courseId);
  const override = TEST_OVERRIDES.get(courseId);
  // Always a fresh view: callers can never mutate the generated table.
  return {
    ...base,
    capabilities: { ...base.capabilities, ...override },
    artifacts: { ...base.artifacts },
  };
}

export function hasCapability(courseId: string, capability: keyof CourseCapabilities): boolean {
  return courseProfile(courseId).capabilities[capability] === true;
}

export function allCourseProfiles(): CourseProfile[] {
  return Object.keys(PROFILES)
    .sort()
    .map((id) => courseProfile(id));
}

/**
 * The capability a "magic" lesson route id needs, or undefined for a real
 * lesson id / the course-agnostic magic ids ("srs", "mistakes").
 */
export function lessonRouteCapability(lessonId: string): keyof CourseCapabilities | undefined {
  switch (lessonId) {
    case "srs-listening":
      return "listening";
    case "srs-speaking":
      return "speaking";
    case "writing-practice":
      return "writing";
    case "conversation":
      return "conversation";
    default:
      return undefined;
  }
}
